style.css:
@-moz-document domain("lichess.org") {
/* ? Cambiar color del fondo general */
body {
  background: radial-gradient(circle at center, #1a1a1a 0%, #000000 100%) !important;
  color: #e0e0e0 !important;
}

/* ♟️ Cambiar tablero de ajedrez */
.cg-board {
  background-image: url("https://upload.wikimedia.org/wikipedia/commons/6/6f/Chess_board_alternative_green.png") !important;
  background-size: cover !important;
}

/* ? Cambiar las piezas de ajedrez */
.piece {
  background-size: contain !important;
  background-repeat: no-repeat !important;
}

/* Blancas */
.piece.pawn.white   { background-image: url("https://imgur.com/a/ROlSm3j") !important; }
.piece.knight.white { background-image: url("https://upload.wikimedia.org/wikipedia/commons/2/28/Chess_nlt45.svg") !important; }
.piece.bishop.white { background-image: url("https://upload.wikimedia.org/wikipedia/commons/9/9b/Chess_blt45.svg") !important; }
.piece.rook.white   { background-image: url("https://upload.wikimedia.org/wikipedia/commons/5/5c/Chess_rlt45.svg") !important; }
.piece.queen.white  { background-image: url("https://upload.wikimedia.org/wikipedia/commons/4/49/Chess_qlt45.svg") !important; }
.piece.king.white   { background-image: url("https://upload.wikimedia.org/wikipedia/commons/3/3b/Chess_klt45.svg") !important; }

/* Negras */
.piece.pawn.black   { background-image: url("https://upload.wikimedia.org/wikipedia/commons/c/c7/Chess_pdt45.svg") !important; }
.piece.knight.black { background-image: url("https://upload.wikimedia.org/wikipedia/commons/f/f1/Chess_ndt45.svg") !important; }
.piece.bishop.black { background-image: url("https://upload.wikimedia.org/wikipedia/commons/8/81/Chess_bdt45.svg") !important; }
.piece.rook.black   { background-image: url("https://upload.wikimedia.org/wikipedia/commons/a/a0/Chess_rdt45.svg") !important; }
.piece.queen.black  { background-image: url("https://upload.wikimedia.org/wikipedia/commons/a/af/Chess_qdt45.svg") !important; }
.piece.king.black   { background-image: url("https://upload.wikimedia.org/wikipedia/commons/e/e3/Chess_kdt45.svg") !important; }

/* ✨ Cambiar el color de resaltado de movimientos */
.square.move-dest, .square.last-move {
  background-color: rgba(255, 215, 0, 0.4) !important;
}

/* ? Personalizar fuente y color del texto */
.lichess {
  font-family: 'Roboto Mono', monospace !important;
  color: #f2f2f2 !important;
}

/* ? Efecto al pasar el ratón sobre piezas */
.piece:hover {
  filter: drop-shadow(0px 0px 8px gold) brightness(1.2);
  transform: scale(1.05);
  transition: all 0.2s ease-in-out;
}
}
